        f1[254] = test_input[254];
        f1[255] = test_input[255];
        $display("=== Loading Dilithium zeta ROM (256 entries) ===");
        load_zeta_rom();
        $display("  Zeta ROM loaded OK");

        // ---- Test 1: forward NTT bit-exact vs golden ----
        $display("\n=== Test 1: Forward NTT bit-exact vs golden ===");
        load_poly();
        start = 1; inverse = 0; @(posedge clk); start = 0;
        wait_done(); read_poly();
        errors = 0;
        for (i = 0; i < 256; i = i + 1) begin
            if (coeff_out[i] !== gold_ntt[i]) begin
                if (errors < 8) $display("MISMATCH[%0d]: got %0d expected %0d", i, $signed(coeff_out[i]), $signed(gold_ntt[i]));
                errors = errors + 1; end
        end
        if (errors == 0) $display("  PASS: forward NTT bit-exact (256/256)");
        else $display("  FAIL: %0d mismatches", errors);

        // ---- Test 2: forward range ----
        errors = 0;
        for (i = 0; i < 256; i = i + 1)
            if ($signed(coeff_out[i]) < -(QD/2) || $signed(coeff_out[i]) > QD/2) errors = errors + 1;
        if (errors == 0) $display("  PASS: all coeffs in [-q/2,q/2]");
        else $display("  FAIL: %0d out of range", errors);

        // ---- Test 3: round-trip invntt(ntt(f)) == f*R mod q ----
        $display("\n=== Test 3: NTT/INTT round-trip (5 polys) ===");
        errors = 0;
        for (t = 0; t < 5; t = t + 1) begin
            for (i = 0; i < 256; i = i + 1) begin
                test_input[i] = rt_poly[t*256 + i];
                orig_f[i]     = rt_poly[t*256 + i];
            end
            load_poly();
            start = 1; inverse = 0; @(posedge clk); start = 0;
            wait_done(); read_poly();
            for (i = 0; i < 256; i = i + 1) test_input[i] = coeff_out[i];
            load_poly();
            start = 1; inverse = 1; @(posedge clk); start = 0;
            wait_done(); read_poly();
            for (i = 0; i < 256; i = i + 1) begin
                reg [31:0] exp, got;
                reg [63:0] prod64;
                prod64 = orig_f[i] * R_MOD;          // f*R needs 27+17=44 bits; 32-bit would overflow
                exp = prod64 % QD;
                got = ((($signed(coeff_out[i]) % QD) + QD) % QD);
                if (got != exp) begin
                    if (errors < 8) $display("RT-MISMATCH poly %0d [%0d]: got %0d exp %0d", t, i, got, exp);
                    errors = errors + 1; end
            end
        end
        if (errors == 0) $display("  PASS: invntt(ntt(f))==f*R mod q (5/5 polys)");
        else $display("  FAIL: %0d mismatches", errors);

        // ---- Test 4: INTT(0) == 0 ----
        $display("\n=== Test 4: INTT(0) ===");
        for (i = 0; i < 256; i = i + 1) test_input[i] = {BW{1'b0}};
        load_poly();
        start = 1; inverse = 0; @(posedge clk); start = 0;
        wait_done(); read_poly();
        for (i = 0; i < 256; i = i + 1) test_input[i] = coeff_out[i];
        load_poly();
        start = 1; inverse = 1; @(posedge clk); start = 0;
        wait_done(); read_poly();
        errors = 0;
        for (i = 0; i < 256; i = i + 1) begin
            reg [31:0] got; got = ((($signed(coeff_out[i]) % QD) + QD) % QD);
            if (got != 0) errors = errors + 1;
        end
        if (errors == 0) $display("  PASS: invntt(ntt(0)) == 0");
        else $display("  FAIL: %0d non-zero", errors);

        // ---- Test 5: INTT of the VERIFIED forward vector (isolates INTT) ----
        $display("\n=== Test 5: INTT(gold_ntt) == f1*R (isolated inverse) ===");
        for (i = 0; i < 256; i = i + 1) test_input[i] = gold_ntt[i];
        load_poly();
        start = 1; inverse = 1; @(posedge clk); start = 0;
        wait_done(); read_poly();
        errors = 0;
        for (i = 0; i < 256; i = i + 1) begin
            reg [31:0] exp5, got5;
            reg [63:0] prod64;
            prod64 = f1[i] * R_MOD;                  // f*R needs 27+17=44 bits; 32-bit would overflow
            exp5 = prod64 % QD;
            got5 = ((($signed(coeff_out[i]) % QD) + QD) % QD);
            if (got5 != exp5) begin
                if (errors < 10) $display("INTT-MISMATCH[%0d]: got %0d exp %0d", i, got5, exp5);
                errors = errors + 1; end
        end
        if (errors == 0) $display("  PASS: INTT(gold_ntt) == f1*R (256/256)");
        else $display("  FAIL: %0d mismatches", errors);


        // ---- Test 6: GOLD STANDARD -- invntt(ntt(a) o ntt(b)) == a*b*R ----
        // plain pointwise product (not fqmul): the mathematical NTT is
        // multiplicative, so the full INTT must return the negacyclic
        // convolution times R.  This is the real application property.
        $display("\n=== Test 6: poly_mul == schoolbook negacyclic conv * R ===");
        for (i = 0; i < 256; i = i + 1) begin
            test_input[i] = rt_poly[i];
        end
        load_poly();
        start = 1; inverse = 0; @(posedge clk); start = 0;
        wait_done(); read_poly();
        for (i = 0; i < 256; i = i + 1) av[i] = coeff_out[i];
        for (i = 0; i < 256; i = i + 1) begin
            test_input[i] = rt_poly[256 + i];
        end
        load_poly();
        start = 1; inverse = 0; @(posedge clk); start = 0;
        wait_done(); read_poly();
        for (i = 0; i < 256; i = i + 1) bv[i] = coeff_out[i];
        for (i = 0; i < 256; i = i + 1) begin
            reg [31:0] ua, ub;
            reg [63:0] pr;
            ua = ((($signed(av[i]) % QD) + QD) % QD);
            ub = ((($signed(bv[i]) % QD) + QD) % QD);
            pr = ua * ub;
            pt[i] = (pr % QD);
        end
        for (i = 0; i < 256; i = i + 1) test_input[i] = pt[i];
        load_poly();
        start = 1; inverse = 1; @(posedge clk); start = 0;
        wait_done(); read_poly();
        errors = 0;
        for (i = 0; i < 256; i = i + 1) begin
            reg [31:0] gu, xu;
            reg [63:0] gp;
            gu = ((($signed(gold_mul[i]) % QD) + QD) % QD);
            gp = $signed(coeff_out[i]) % QD;
            xu = ((gp + QD) % QD);
            if (xu != gu) begin
                if (errors < 8) $display("MUL-MISMATCH[%0d]: got %0d expected %0d", i, xu, gu);
                errors = errors + 1; end
        end
        if (errors == 0) $display("  PASS: poly_mul == schoolbook conv * R (256/256)");
        else $display("  FAIL: %0d mismatches", errors);

        $display("\n=== SIGN-mode tests done ===");
        $finish;
    end
